#include "current_numeric_guess.hpp"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <cstring>
std::uint64_t u(std::ifstream& f){std::uint64_t n;f.read(reinterpret_cast<char*>(&n),8);if(!f)throw std::runtime_error("truncated");return n;}
Eigen::MatrixXd matrix(std::ifstream& f){auto r=u(f),c=u(f);if(r>20000||c>144||r*c>3000000)throw std::runtime_error("shape");Eigen::MatrixXd m(r,c);for(auto i=0ULL;i<r;++i)for(auto j=0ULL;j<c;++j){f.read(reinterpret_cast<char*>(&m(i,j)),8);if(!f)throw std::runtime_error("truncated");}return m;}
Eigen::VectorXd vector(std::ifstream& f){auto n=u(f);if(n>20000)throw std::runtime_error("shape");Eigen::VectorXd x(n);f.read(reinterpret_cast<char*>(x.data()),8*n);if(!f)throw std::runtime_error("truncated");return x;}
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("fixture required");std::ifstream in(argv[1],std::ios::binary);auto H=matrix(in);auto g=vector(in);auto A=matrix(in);auto lo=vector(in);auto hi=vector(in);auto seed=vector(in);auto primal=vector(in);auto k=u(in);std::vector<phase5_dynamic_numeric_v1::Face> faces;for(auto i=0ULL;i<k;++i){auto row=u(in);std::int64_t side;in.read(reinterpret_cast<char*>(&side),8);faces.push_back({static_cast<int>(row),static_cast<int>(side)});}char tail;if(in.get(tail))throw std::runtime_error("trailing");auto replay=phase5_dynamic_numeric_v1::derive(H,g,A,lo,hi,seed);if(!replay.complete)throw std::runtime_error("repaired same saved genuine currentQP refused: "+replay.error);auto axFinal=A*replay.primal;double violation=std::max({0.,(lo-axFinal).maxCoeff(),(axFinal-hi).maxCoeff()});double stationarity=(H*replay.primal+g+A.transpose()*replay.dual).lpNorm<Eigen::Infinity>();if(violation>1e-12||stationarity>1e-10)throw std::runtime_error("original hint final gates failed");std::cout<<std::setprecision(17)<<"REPAIRED_SAME_CURRENTQP_PASS events="<<replay.events.size()<<" violation="<<violation<<" stationarity="<<stationarity<<" zero_step_diagnostics="<<replay.boundary_events.size()<<" singular_KKT_diagnostics="<<replay.rank_events.size()<<" noModel_noNativeOSQP_noTasksteps=1\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
